1	/**
2	 * Everything the plugin decides, with nothing from the SDK in it.
3	 *
4	 * A key face is a function of what the plugin knows: whether it is
5	 * signed in, whether its socket is open, which runs are held, which is
6	 * pinned, and what that run last published. `reduce` moves the state on
7	 * one event at a time; the `*Face` functions read it. Keeping them pure
8	 * is what lets the twelve states a key can be in have a test each.
9	 */
10	
11	/**
12	 * What a deck may press, right now, in the pack's own words.
13	 *
14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
15	 * from `apps/web`, so this shape is mirrored rather than shared.
16	 */
17	export interface Offer {
18	  seq: number;
19	  /**
20	   * The one press the run is waiting on.
21	   *
22	   * `owed` is a threshold or a global roll the run owes, which a deck
23	   * presses like any other primary: the page decides what it turns into.
24	   */
25	  primary: { id: "roll" | "carry-on" | "close" | "enter" | "owed"; label: string; kind: string } | null;
26	  moves: Array<{ id: string; label: string }>;
27	  undo: { what: string } | null;
28	  /** Why a deck cannot press this, in words a key face can carry. */
29	  needsPage: string | null;
30	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
31	  /**
32	   * The setups the run could hand out, empty where the run names no tool or is
33	   * not live, and absent from an older page's offer entirely.
34	   */
35	  setups?: Array<{ id: string; title: string }>;
36	  /**
37	   * The setups the run could send a tool once, without touching the run's
38	   * own setup - empty where the run names no tool or is not live, and
39	   * absent from an older page's offer entirely.
40	   */
41	  commands?: Array<{ id: string; title: string }>;
42	  /**
43	   * The counters and resources this run will take a change to, from a deck
44	   * as from the page - absent from an older page's offer entirely.
45	   */
46	  trackers?: Array<{ id: string; kind: "counter" | "resource"; label: string; value: number; max: number | null }>;
47	  /**
48	   * The clock a deck may pause, resume or stop, or nothing where the run
49	   * keeps none - absent from an older page's offer entirely.
50	   */
51	  clock?: { id: string; label: string; status: "running" | "paused" | "done" } | null;
52	  /** Whether the run is rolling for itself rather than waiting on a press, or absent from an older page's offer. */
53	  autoRoll?: boolean;
54	  /** How the run would end if it were finished now, or nothing while it cannot be, or absent from an older page's offer. */
55	  ending?: { label: string } | null;
56	}
57	
58	export type SessionState = "none" | "expired" | "ok";
59	export type SocketState = "closed" | "connecting" | "open";
60	export interface HeldRun {
61	  id: string;
62	  name?: string;
63	  packTitle?: string;
64	}
65	export interface Snapshot {
66	  /** The run as the server knows it, which is where the pack's id travels. */
67	  run?: { id?: string; packId?: string };
68	  unit?: number;
69	  words?: { unit: string };
70	  score?: { text: string };
71	  latest?: { text: string } | null;
72	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
73	  standings?: Array<{ name: string; points: number; place: number }>;
74	  counters?: Array<{ id: string; label: string; value: number }>;
75	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
76	  at?: string;
77	  offer?: Offer;
78	}
79	export interface DeckState {
80	  session: SessionState;
81	  /** Whether the streamer has switched the deck on. No socket while false. */
82	  on: boolean;
83	  /** Whether the last time it went off, it was the idle timer rather than a press. */
84	  idleOff: boolean;
85	  socket: SocketState;
86	  runs: HeldRun[];
87	  any: boolean;
88	  pinned: string | null;
89	  attached: string | null;
90	  snapshot: Snapshot | null;
91	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
92	}
93	/**
94	 * How a face is drawn, by what the key is for rather than by how it feels.
95	 *
96	 * `live` is a key that moves the run - Next, Roll, Press - and it is the
97	 * only one that takes the celadon edge. `undo` is the same lit face with
98	 * the kiln edge, because taking a result back is the consequence the
99	 * second accent is for. `readout` is a Metric key, which is a number
100	 * rather than a button: the app's own ground, a hairline, and lit ink.
101	 * `deck` is the furniture - Connect, Run, Open, Apply setup - lit, but
102	 * without an accent claiming it does something to the run. `dim` and
103	 * `refuse` are states rather than families and belong to every key.
104	 */
105	export type Tone = "live" | "dim" | "refuse" | "undo" | "readout" | "deck";
106	export interface Face {
107	  title: string;
108	  tone: Tone;
109	  when?: string;
110	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
111	  fraction?: number;
112	}
113	export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
114	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
115	/** What a short press of an adjustable Metric key does: step it up by one, or put it at a number. */
116	export type MetricPress = { kind: "step" } | { kind: "set"; value: number };
117	/** The answer form of a press, which is how everything but the primary and undo goes over the wire. */
118	export type AnswerPress = { press: "answer"; answer: Record<string, unknown> };
119	export type DeckEvent =
120	  | { t: "session"; state: SessionState }
121	  | { t: "on"; on: boolean; idle?: boolean }
122	  | { t: "socket"; state: SocketState }
123	  | { t: "runs"; runs: HeldRun[]; any: boolean }
124	  | { t: "pin"; id: string | null }
125	  | { t: "snapshot"; snapshot: Snapshot }
126	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
127	  | { t: "tick" };
128	
129	const FLASH_MS = 3000;
130	
131	/** How long a connection that is holding nothing waits before closing itself. */
132	export const IDLE_OFF_MS = 30 * 60_000;
133	
134	export function initial(): DeckState {
135	  return {
136	    session: "none",
137	    on: false,
138	    idleOff: false,
139	    socket: "closed",
140	    runs: [],
141	    any: false,
142	    pinned: null,
143	    attached: null,
144	    snapshot: null,
145	    flash: null,
146	  };
147	}
148	
149	export function attachedRun(state: DeckState): string | null {
150	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
151	  return state.runs.length === 1 ? state.runs[0]!.id : null;
152	}
153	
154	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
155	  switch (event.t) {
156	    case "session":
157	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
158	    case "on":
159	      // Going off is a full stop: no socket, nothing held, nothing to draw
160	      // a number from. The pin is a preference, not a holding, and stays.
161	      return event.on
162	        ? { ...state, on: true, idleOff: false }
163	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
164	    case "socket":
165	      return event.state === "open"
166	        ? { ...state, socket: "open" }
167	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
168	    case "runs": {
169	      const next = { ...state, runs: event.runs, any: event.any };
170	      const attached = attachedRun(next);
171	      // A run that went away takes its numbers with it; a run that is
172	      // still here keeps them until the next snapshot lands.
173	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
174	    }
175	    case "pin": {
176	      const next = { ...state, pinned: event.id };
177	      const attached = attachedRun(next);
178	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
179	    }
180	    case "snapshot":
181	      return { ...state, snapshot: event.snapshot };
182	    case "drove": {
183	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
184	      // A `drove` verdict is the freshest seq source: the next press
185	      // should not carry a seq gone stale while it was in flight.
186	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
187	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
188	    }
189	    case "tick": {
190	      const expired = state.flash !== null && state.flash.until <= now;
191	      // Controller ruling 3: a dial redraws every second while a clock is
192	      // running, so its remaining time keeps moving between snapshots. An
193	      // idle deck has nothing that changes on the tick, so it stays the
194	      // same object and nothing redraws.
195	      const running = state.snapshot?.clocks?.some((c) => c.status === "running") ?? false;
196	      if (!expired && !running) return state;
197	      return expired ? { ...state, flash: null } : { ...state };
198	    }
199	  }
200	}
201	
202	/** What a key says about the run once the deck is signed in and switched on. */
203	function held(state: DeckState): Face | null {
204	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
205	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
206	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
207	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
208	  return null;
209	}
210	
211	/** The state every key shares before any of them has something of its own to say. */
212	function common(state: DeckState): Face | null {
213	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
214	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
215	  // A key that depends on the connection says to make it first: the state
216	  // on top, the thing to do about it beneath.
217	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
218	  return held(state);
219	}
220	
221	/** The run a deck is following, named, or nothing. */
222	function attachedName(state: DeckState): Face | null {
223	  const run = state.runs.find((r) => r.id === state.attached);
224	  if (!run) return null;
225	  return { title: run.name ?? run.packTitle ?? run.id, tone: "deck", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
226	}
227	
228	/**
229	 * The Connect key, which reports the connection rather than the run behind it.
230	 *
231	 * It is the one key that has something to say while the deck is off, so it
232	 * skips the "Not connected" every other key stops at and names the state it
233	 * is actually in - down by choice, down by the idle timer, or on its way up.
234	 * Once the socket is open it says **Disconnect**, one press away from off -
235	 * which run that carries, if any, is the Run key's business, not this one's.
236	 */
237	export function connectFace(state: DeckState): Face {
238	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
239	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
240	  if (!state.on) return { title: "Connect", tone: "dim", when: state.idleOff ? "went idle" : undefined };
241	  if (state.socket !== "open") return { title: "Connecting", tone: "dim" };
242	  return { title: "Disconnect", tone: "deck" };
243	}
244	
245	/**
246	 * When a connection that is holding nothing should close itself.
247	 *
248	 * `since` is when it last had nothing to follow. Null means the clock is not
249	 * running at all - a deck following a live run never times out, however long
250	 * the stream goes, and a deck that is off or still dialing has nothing to
251	 * give up on.
252	 */
253	export function idleDeadline(state: DeckState, since: number): number | null {
254	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
255	  return since + IDLE_OFF_MS;
256	}
257	
258	function flashed(state: DeckState): Face | null {
259	  if (!state.flash || state.flash.ok) return null;
260	  return { title: state.flash.say ?? "No", tone: "refuse" };
261	}
262	
263	/** What the follow key was told about decisions. Re-exported by `actions/next.ts`. */
264	export type NextSettings = { stop?: boolean };
265	
266	/**
267	 * The decision the follow key takes for the streamer, or nothing.
268	 *
269	 * A checklist first, then a declaration with something to suggest: the two
270	 * the page publishes as presets. Placing the key and leaving *Stop at
271	 * decisions* unticked is the streamer choosing to skip the reading, which
272	 * is the rule `apps/web/src/run/handsFree.ts` asks for - a decision is
273	 * skipped only where somebody chose to skip it.
274	 */
275	function decision(offer: Offer, settings: NextSettings): Offer["presets"][number] | null {
276	  if (settings.stop) return null;
277	  const list = offer.presets.find((p) => p.kind === "checklist");
278	  if (list) return list;
279	  return offer.presets.find((p) => p.kind === "declareSubject" && (p.suggestions?.[0] ?? "") !== "") ?? null;
280	}
281	
282	/** What one press of the follow key sends, or nothing for it to send. */
283	export function nextPress(
284	  state: DeckState,
285	  settings: NextSettings,
286	): { press: "primary" } | { press: "answer"; answer: Record<string, string> } | null {
287	  const offer = state.snapshot?.offer;
288	  if (!offer) return null;
289	  if (offer.primary) return { press: "primary" };
290	  const d = decision(offer, settings);
291	  if (!d) return null;
292	  // The words the page takes for each preset, from `takePress.ts`.
293	  return d.kind === "checklist"
294	    ? { press: "answer", answer: { ticks: "all" } }
295	    : { press: "answer", answer: { subject: d.suggestions![0]! } };
296	}
297	
298	export function nextFace(state: DeckState, settings: NextSettings): Face {
299	  const c = common(state) ?? flashed(state);
300	  if (c) return c;
301	  const offer = state.snapshot?.offer;
302	  if (!offer) return { title: "Loading…", tone: "dim" };
303	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
304	  // What the key would take, in the page's own words: the checklist's
305	  // button, or the name it would declare with the ask beneath it.
306	  const d = decision(offer, settings);
307	  if (d?.kind === "checklist") return { title: d.label, tone: "live" };
308	  if (d) return { title: d.suggestions![0]!, tone: "live", when: d.label };
309	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
310	}
311	
312	export function pressFace(state: DeckState, target: PressTarget): Face {
313	  const c = common(state) ?? flashed(state);
314	  if (c) return c;
315	  const offer = state.snapshot?.offer;
316	  if (!offer) return { title: "Loading…", tone: "dim" };
317	  if (target.kind === "roll")
318	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
319	  if (target.kind === "move") {
320	    const m = offer.moves.find((x) => x.id === target.id);
321	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
322	  }
323	  const p = offer.presets.find((x) => x.kind === target.preset);
324	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
325	}
326	
327	/** What the dedicated Roll key says: the waiting roll, in its own words, or nothing to roll. */
328	export function rollFace(state: DeckState): Face {
329	  const c = common(state) ?? flashed(state);
330	  if (c) return c;
331	  const offer = state.snapshot?.offer;
332	  if (!offer) return { title: "Loading…", tone: "dim" };
333	  return offer.primary?.id === "roll"
334	    ? { title: offer.primary.label, tone: "live", when: "Roll" }
335	    : { title: "Nothing to roll", tone: "dim" };
336	}
337	
338	/** What the setup key says: what it applies and hands out, whether that is on offer, or nothing chosen at all. */
339	export function setupFace(state: DeckState, setup?: { id: string; title: string }): Face {
340	  const c = common(state) ?? flashed(state);
341	  if (c) return c;
342	  if (!setup) return { title: "Set up", tone: "dim" };
343	  const offer = state.snapshot?.offer;
344	  if (!offer) return { title: "Loading…", tone: "dim" };
345	  // `?? []`: an older page's offer may not name any setups at all.
346	  return (offer.setups ?? []).some((s) => s.id === setup.id)
347	    ? { title: setup.title, tone: "deck", when: "Apply setup" }
348	    : { title: setup.title, tone: "dim", when: "Not here" };
349	}
350	
351	/** What the Command key says: the setup it would send the tool once, whether that is on offer, or nothing chosen at all. */
352	export function commandFace(state: DeckState, command?: { id: string; title: string }): Face {
353	  const c = common(state) ?? flashed(state);
354	  if (c) return c;
355	  if (!command) return { title: "Set up", tone: "dim" };
356	  const offer = state.snapshot?.offer;
357	  if (!offer) return { title: "Loading…", tone: "dim" };
358	  // `?? []`: an older page's offer may not name any commands at all.
359	  return (offer.commands ?? []).some((x) => x.id === command.id)
360	    ? { title: command.title, tone: "live", when: "Send to tool" }
361	    : { title: command.title, tone: "dim", when: "Not here" };
362	}
363	
364	export function undoFace(state: DeckState): Face {
365	  const c = common(state) ?? flashed(state);
366	  if (c) return c;
367	  const undo = state.snapshot?.offer?.undo;
368	  // The key says "Undo" either way: what it would take back is the run's
369	  // business, and a key too small to read it is no help at the table.
370	  return undo ? { title: "Undo", tone: "undo" } : { title: "Undo", tone: "dim" };
371	}
372	
373	/** Where the Open key points, chosen in its settings. */
374	export type OpenTarget = "run" | "guide" | "rules" | "newrun" | "dock";
375	
376	/** What each page is called on the key, the guide aside. */
377	const OPEN_LABELS: Record<Exclude<OpenTarget, "guide">, string> = {
378	  run: "Open the run",
379	  rules: "Rules",
380	  newrun: "A new run",
381	  dock: "The dock",
382	};
383	
384	/**
385	 * What the Open key says: the page it would put in front of the streamer.
386	 *
387	 * The guide is the one target that needs nothing - no account, no
388	 * connection, no run - so it skips the gating every other key stops at.
389	 * The rest name something the deck is holding, so they say what is missing
390	 * the way the rest of the deck does.
391	 */
392	export function openFace(state: DeckState, target?: OpenTarget): Face {
393	  if (!target) return { title: "Set up", tone: "dim" };
394	  if (target === "guide") return { title: "Guide", tone: "deck", when: "in a browser" };
395	  // `newrun` opens `/create`, which needs no run to already be held, so it
396	  // is answered beside `guide` rather than waiting on `common()`.
397	  if (target === "newrun") return { title: OPEN_LABELS.newrun, tone: "deck", when: "in a browser" };
398	  const c = common(state);
399	  if (c) return c;
400	  return { title: OPEN_LABELS[target], tone: "deck", when: "in a browser" };
401	}
402	
403	export function runFace(state: DeckState): Face {
404	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
405	}
406	
407	/** How far a clock has moved since the snapshot that reported it, in ms. */
408	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
409	  const since = c.status === "running" ? now - Date.parse(at) : 0;
410	  return c.elapsedMs + since;
411	}
412	
413	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
414	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
415	  const elapsed = clockElapsedMs(c, at, now);
416	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
417	  const s = Math.floor(ms / 1000);
418	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
419	}
420	
421	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
422	  const c = common(state);
423	  if (c) return c;
424	  const snap = state.snapshot;
425	  if (!snap) return { title: "Loading…", tone: "dim" };
426	  if (field === "score") return { title: snap.score?.text ?? "–", tone: "readout", when: "Score" };
427	  if (field === "unit") return { title: String(snap.unit ?? "–"), tone: "readout", when: snap.words?.unit ?? "Unit" };
428	  if (field === "latest") return { title: snap.latest?.text ?? "–", tone: "readout" };
429	  if (field === "leader") {
430	    const top = snap.standings?.[0];
431	    return top ? { title: top.name, tone: "readout", when: `${top.points} pts` } : { title: "–", tone: "dim", when: "Leader" };
432	  }
433	  if (field === "clock") {
434	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
435	    if (!clock || !snap.at) return { title: "–", tone: "dim", when: "Clock" };
436	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
437	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
438	    return { title: clockText(clock, snap.at, now), tone: "readout", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
439	  }
440	  if ("counter" in field) {
441	    const x = snap.counters?.find((k) => k.id === field.counter);
442	    return x ? { title: String(x.value), tone: "readout", when: x.label } : { title: "–", tone: "dim" };
443	  }
444	  const r = snap.resources?.find((k) => k.id === field.resource);
445	  return r
446	    ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "readout", when: r.label }
447	    : { title: "–", tone: "dim" };
448	}
449	
450	/**
451	 * The tracker a Metric key would move, or nothing where it cannot move one.
452	 *
453	 * Only a counter or a resource: the score, the unit, a clock, the last
454	 * result and the leader are the run's own arithmetic and a key set to one
455	 * of those is a readout. The offer names which trackers the run will take a
456	 * change to, so a key set to a number this run does not keep presses
457	 * nothing rather than being refused on the way out. `?? []` for an older
458	 * page, whose offer names none at all.
459	 */
460	function trackerOf(state: DeckState, field: MetricField | undefined): string | null {
461	  if (!field || typeof field === "string") return null;
462	  const id = "counter" in field ? field.counter : field.resource;
463	  const kind = "counter" in field ? "counter" : "resource";
464	  const offer = state.snapshot?.offer;
465	  return (offer?.trackers ?? []).some((t) => t.id === id && t.kind === kind) ? id : null;
466	}
467	
468	/**
469	 * What one press of a Metric key sends, or nothing for it to send.
470	 *
471	 * A short press does what the key was set to: one up, or straight to a
472	 * number. A hold takes one back off, whichever way it was set, because a
473	 * key that can only count up is a key you have to reach past to the page
474	 * the first time you miscount.
475	 */
476	export function metricPress(
477	  state: DeckState,
478	  field: MetricField | undefined,
479	  press: MetricPress | undefined,
480	  long: boolean,
481	): AnswerPress | null {
482	  const tracker = trackerOf(state, field);
483	  if (!tracker) return null;
484	  if (long) return { press: "answer", answer: { tracker, by: -1 } };
485	  return press?.kind === "set"
486	    ? { press: "answer", answer: { tracker, to: press.value } }
487	    : { press: "answer", answer: { tracker, by: 1 } };
488	}
489	
490	/**
491	 * What the Clock key says: the run's clock, and what pressing it would do.
492	 *
493	 * The same arithmetic a Metric key set to the clock draws, in the tone of a
494	 * key that moves something rather than a readout. A paused clock keeps its
495	 * time on the face and says so underneath; a clock that has run out says
496	 * the same thing the page does.
497	 */
498	export function clockFace(state: DeckState, now: number): Face {
499	  const c = common(state) ?? flashed(state);
500	  if (c) return c;
501	  const snap = state.snapshot;
502	  if (!snap?.offer) return { title: "Loading…", tone: "dim" };
503	  // `?? null` for an older page, which names no clock on its offer at all.
504	  const clock = snap.offer.clock ?? null;
505	  if (!clock) return { title: "No clock", tone: "dim" };
506	  if (clock.status === "done") return { title: "0:00", tone: "dim", when: "done" };
507	  const kept = snap.clocks?.find((x) => x.id === clock.id);
508	  if (!kept || !snap.at) return { title: "–", tone: "dim", when: clock.label };
509	  const text = clockText(kept, snap.at, now);
510	  if (clock.status === "paused") return { title: text, tone: "dim", when: "paused" };
511	  const counting = kept.kind === "timer" && kept.seconds !== null;
512	  const fraction = counting ? clockElapsedMs(kept, snap.at, now) / (kept.seconds! * 1000) : undefined;
513	  return { title: text, tone: "live", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
514	}
515	
516	/** What one press of the Clock key sends: the stop on a hold, the pause or the resume on a tap. */
517	export function clockPress(state: DeckState, long: boolean): AnswerPress | null {
518	  const clock = state.snapshot?.offer?.clock;
519	  if (!clock || clock.status === "done") return null;
520	  if (long) return { press: "answer", answer: { clock: clock.id, do: "stop" } };
521	  return { press: "answer", answer: { clock: clock.id, do: clock.status === "running" ? "pause" : "resume" } };
522	}
523	
524	/**
525	 * What the Keep rolling key says: who is throwing the dice.
526	 *
527	 * The same words either way underneath, because twenty characters is not
528	 * room for two different sentences and the key is a switch: what it says on
529	 * top is the state, and pressing it is the other one.
530	 */
531	export function autoRollFace(state: DeckState): Face {
532	  const c = common(state) ?? flashed(state);
533	  if (c) return c;
534	  const offer = state.snapshot?.offer;
535	  if (!offer) return { title: "Loading…", tone: "dim" };
536	  // `?? false` for an older page: a run that says nothing about this is one
537	  // rolling by hand.
538	  return (offer.autoRoll ?? false)
539	    ? { title: "Rolling for you", tone: "live", when: "press to switch" }
540	    : { title: "Roll by hand", tone: "deck", when: "press to switch" };
541	}
542	
543	/** What one press of the Keep rolling key sends: the other setting. */
544	export function autoRollPress(state: DeckState): AnswerPress | null {
545	  const offer = state.snapshot?.offer;
546	  if (!offer) return null;
547	  return { press: "answer", answer: { autoRoll: !(offer.autoRoll ?? false) } };
548	}
549	
550	/**
551	 * What the Finish key says: how the run would end, or that it cannot yet.
552	 *
553	 * The kiln edge, which is the accent for a press there is no coming back
554	 * from, and the hold is the other half of the same guard: a run does not
555	 * end because somebody brushed a key mid-scene.
556	 */
557	export function finishFace(state: DeckState): Face {
558	  const c = common(state) ?? flashed(state);
559	  if (c) return c;
560	  const offer = state.snapshot?.offer;
561	  if (!offer) return { title: "Loading…", tone: "dim" };
562	  // `?? null` for an older page, whose offer says nothing about an ending.
563	  const ending = offer.ending ?? null;
564	  return ending ? { title: ending.label, tone: "refuse", when: "hold to finish" } : { title: "Not yet", tone: "dim" };
565	}
566	
567	/** What a held Finish key sends, or nothing where the run has no ending to take. */
568	export function finishPress(state: DeckState): AnswerPress | null {
569	  return state.snapshot?.offer?.ending ? { press: "answer", answer: { finish: true } } : null;
570	}
571

