1	import streamDeck from "@elgato/streamdeck";
2	
3	import { AutoRoll } from "./actions/autoroll.ts";
4	import { Clock } from "./actions/clock.ts";
5	import { Command } from "./actions/command.ts";
6	import { Connect } from "./actions/connect.ts";
7	import { Finish } from "./actions/finish.ts";
8	import { Metric } from "./actions/metric.ts";
9	import { Next } from "./actions/next.ts";
10	import { Open } from "./actions/open.ts";
11	import { Press } from "./actions/press.ts";
12	import { Roll } from "./actions/roll.ts";
13	import { pin, Run, runsForInspector } from "./actions/run.ts";
14	import { Setup } from "./actions/setup.ts";
15	import { Undo } from "./actions/undo.ts";
16	import { profileFor } from "./profiles.ts";
17	import { loadSession, normalizeBase, signIn, signOut, type Account } from "./session.ts";
18	import { openWire } from "./socket.ts";
19	import { makeStore } from "./store.ts";
20	import { idleDeadline, type DeckState } from "./state.ts";
21	
22	/** Where Runlog lives when the streamer has not said otherwise. */
23	const DEFAULT_API = "https://runlog.scrthq.com";
24	
25	/**
26	 * What the plugin keeps between launches.
27	 *
28	 * The address and the pinned run, and nothing else: global settings are
29	 * handed to the property inspector, which is a web view, so the session
30	 * never comes near them. It lives in a file of the plugin's own.
31	 */
32	type Globals = { apiBase?: string; pinned?: string | null; switchProfiles?: boolean };
33	
34	let base = DEFAULT_API;
35	
36	/** Whether attaching to a run moves the deck to that run's profile. Unset is on. */
37	let switchProfiles = true;
38	
39	/**
40	 * Where Runlog is, for a key that has to name an address rather than
41	 * press through the wire. The normalized global setting, so a deck
42	 * pointed at a copy of the app opens that copy pages.
43	 */
44	export function apiBase(): string {
45	  return base;
46	}
