3	  <head lang="en">
4	    <title>Command Settings</title>
5	    <meta charset="utf-8" />
6	    <script src="sdpi-components.js"></script>
7	  </head>
8	
9	  <body>
10	    <sdpi-item label="Command">
11	      <select id="command"></select>
12	    </sdpi-item>
13	
14	    <div id="runlog-account"></div>
15	    <script src="account.js"></script>
16	    <script>
17	      // The commands are your library for the pack's tool, so they come from
18	      // the plugin on every appear rather than being listed here.
19	      (() => {
20	        const { streamDeckClient } = SDPIComponents;
21	        const command = document.getElementById("command");
22	        let current = null;
23	
24	        const option = (value, label) => {
25	          const o = document.createElement("option");
26	          o.value = JSON.stringify(value);
27	          o.textContent = label;
28	          return o;
29	        };
30	
31	        const fill = (commands) => {
32	          command.replaceChildren(option(null, "Set up"), ...commands.map((c) => option({ id: c.id, title: c.title }, c.title)));
33	          show();
34	        };
35	
36	        // A command option is identified by its id, so a renamed setup still matches.
37	        const show = () => {
38	          const chosen = current?.id ?? null;
39	          const match = [...command.options].find((o) => (JSON.parse(o.value)?.id ?? null) === chosen);
40	          if (match) command.value = match.value;
41	        };
42	
43	        command.addEventListener("change", () => {
44	          current = JSON.parse(command.value);
45	          streamDeckClient.setSettings(current ? { command: current } : {});
46	        });
47	
48	        streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
49	          if (payload?.t === "commands") fill(payload.commands ?? []);
50	        });
51	        void streamDeckClient.getSettings().then(({ settings }) => {
52	          current = settings?.command ?? null;
53	          show();
54	        });
55	        fill([]);
56	      })();
57	    </script>
58	  </body>
59	</html>
